<div class="top"><h1>Notifications envoyées</h1></div>
<?php if ($driver === 'log'): ?><div class="alert a-info">Mode test : les e-mails sont écrits dans un journal et ne partent pas.</div><?php endif; ?>
<div class="stats"><?php $c = array_column($counts, 'n', 'status'); foreach (['sent' => 'Envoyés (7 j)', 'failed' => 'Échecs (7 j)', 'skipped' => 'Non envoyés (7 j)'] as $k => $l): ?><div class="stat"><small><?= e($l) ?></small><strong><?= (int) ($c[$k] ?? 0) ?></strong></div><?php endforeach; ?></div>
<div class="card"><form method="get" style="display:flex;gap:8px;margin-bottom:12px"><select name="status"><?= select_opts(['' => 'Tous', 'sent' => 'Envoyés', 'failed' => 'Échecs', 'skipped' => 'Non envoyés'], get('status')) ?></select><button class="btn btn-sm btn-p">Filtrer</button></form>
<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Date</th><th>Message</th><th>Destinataire</th><th>État</th><th></th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= e(fdate($r['created_at'], true)) ?></td><td><b><?= e($r['subject']) ?></b><br><small class="muted"><?= e($r['event']) ?></small></td><td><?= e($r['to_address'] ?: '—') ?></td>
<td><?= $r['status'] === 'sent' ? '<span class="badge b-ok">Envoyé</span>' : ($r['status'] === 'failed' ? '<span class="badge b-bad">Échec</span>' : '<span class="badge b-warn">Non envoyé</span>') ?><?= $r['error'] ? '<br><small class="muted">' . e($r['error']) . '</small>' : '' ?></td>
<td><?php if ($r['status'] !== 'sent' && $r['to_address']): ?><form method="post" action="/admin/notifications/<?= (int) $r['id'] ?>/renvoyer"><?= csrf_field() ?><button class="btn btn-sm">Renvoyer</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
